{
  "skills": [
    {
      "skill_id": "chalcogenide_pnictide_gap_transfer",
      "rules": [
        {
          "rule_id": "chalcogenide_anion_positive",
          "conditions": {
            "anion_family": "chalcogenide"
          },
          "weight": 0.72,
          "rationale": "Source dielectric transfer gave chalcogenide a strong positive effect; chalcogenide anions open valence-band maxima, widening gaps."
        },
        {
          "rule_id": "pnictide_anion_positive",
          "conditions": {
            "anion_family": "pnictide"
          },
          "weight": 0.81,
          "rationale": "Strongest shared prior among the top anion families; pnictide p-states span the gap, widening experimental band gaps."
        },
        {
          "rule_id": "halide_anion_negative",
          "conditions": {
            "anion_family": "halide"
          },
          "weight": -0.68,
          "rationale": "Halide reversed weight in source; high electronegativity and gap-narrowing carrier levels suppress experimental gaps."
        },
        {
          "rule_id": "metalloid_dominant_positive",
          "conditions": {
            "dominant_family": "metalloid"
          },
          "weight": 0.75,
          "rationale": "High source support with large max effect; metalloid lattices favor wide-gap covalent bonding motifs."
        }
      ],
      "ridge": 1.6,
      "prior_scale": 0.35,
      "semantic_mass_start": 0.42,
      "semantic_mass_end": 0.18,
      "ucb_weight": 0.58,
      "gp_beta_start": 2.2,
      "gp_beta_end": 1.0,
      "gp_xi": 0.012,
      "confidence": 0.66,
      "hypothesis": "Chalcogenide and pnictide anions plus metalloid dominance transfer a positive gap signal from refractive-index physics. Fails when strong anion polarizability or transition-metal d-states collapse the gap."
    },
    {
      "skill_id": "counter_high_z_lanthanide_gap_reversal",
      "rules": [
        {
          "rule_id": "mean_z_very_high_downweighted",
          "conditions": {
            "mean_atomic_number_bin": "mean_z_very_high"
          },
          "weight": -0.35,
          "rationale": "Reverses the uncertain source prior; heavy-element f and d manifolds often pin or close experimental gaps."
        },
        {
          "rule_id": "lanthanide_dominant_negative",
          "conditions": {
            "dominant_family": "lanthanide"
          },
          "weight": -0.55,
          "rationale": "Weak source support for lanthanide; localized f-states introduce mid-gap levels and reduce measured gaps."
        },
        {
          "rule_id": "has_lanthanide_flag_negative",
          "conditions": {
            "lanthanide_flag": "has_lanthanide"
          },
          "weight": -0.42,
          "rationale": "Source lanthanide effect was near zero with low confidence, so counts as a gap-narrowing inhibitor."
        },
        {
          "rule_id": "balanced_stoichiometry_positive",
          "conditions": {
            "max_element_fraction_bin": "balanced"
          },
          "weight": 0.48,
          "rationale": "Balanced compositions in source had positive effects; they support ordered wide-gap stoichiometric compounds."
        }
      ],
      "ridge": 2.4,
      "prior_scale": 0.22,
      "semantic_mass_start": 0.30,
      "semantic_mass_end": 0.08,
      "ucb_weight": 0.45,
      "gp_beta_start": 1.8,
      "gp_beta_end": 0.9,
      "gp_xi": 0.02,
      "confidence": 0.58,
      "hypothesis": "High mean atomic number and lanthanide presence downweight the source's weak positive prior, treating f and d occupancy as a gap-narrowing penalty. Might fail if the target's light-metal oxides dominate."
    }
  ],
  "selected_skill_id": "chalcogenide_pnictide_gap_transfer",
  "lesson": "Anion-family transfer from dielectric source carries the strongest, most interpretable gap signal; mean-Z and lanthanide relations are weak and warrant counter-weighting rather than blind adoption.",
  "revision_summary": "Retained the positive anion and metalloid transfer signal, downweighted low-confidence lanthanide and very-high-Z relations, and selected the chalcogenide/pnictide skill for deployment with a moderate ridge to control variance."
}

{
  "skills": [
    {
      "skill_id": "polar_heteroatom_hydration_core_v3",
      "rules": [
        {
          "rule_id": "hetero_dense_favors_hydration",
          "conditions": {
            "hetero_atom_bin": "hetero_high"
          },
          "weight": 0.75,
          "rationale": "Dense heteroatoms supply hydrogen-bond donors and acceptors plus dipoles, strongly stabilizing the aqueous phase."
        },
        {
          "rule_id": "hydrocarbon_cavity_penalty",
          "conditions": {
            "hetero_atom_bin": "hetero_none"
          },
          "weight": -0.55,
          "rationale": "Pure hydrocarbons offer only dispersion contacts, so cavity formation cost dominates the hydration free energy."
        },
        {
          "rule_id": "compact_solute_bonus",
          "conditions": {
            "smiles_length_bin": "smiles_short"
          },
          "weight": 0.3,
          "rationale": "Source prior favors short SMILES; small solutes pay low cavity cost with polar groups fully solvent exposed."
        },
        {
          "rule_id": "halogen_rich_penalty",
          "conditions": {
            "halogen_bin": "halogen_high"
          },
          "weight": -0.35,
          "rationale": "Heavy halogenation adds bulky hydrophobic surface that degrades hydration despite nominal heteroatom count."
        }
      ],
      "ridge": 0.9,
      "prior_scale": 0.35,
      "semantic_mass_start": 0.4,
      "semantic_mass_end": 0.15,
      "ucb_weight": 0.6,
      "gp_beta_start": 2.2,
      "gp_beta_end": 1.0,
      "gp_xi": 0.01,
      "confidence": 0.6,
      "hypothesis": "Polarity and hydrogen bonding drive hydration plus a source short-SMILES cavity prior, with halogen hydrophobicity separated from heteroatom count. May fail when intramolecular hydrogen bonds shield polar groups."
    },
    {
      "skill_id": "aromatic_surface_ring_downweight_hypothesis",
      "rules": [
        {
          "rule_id": "moderate_hetero_optimum",
          "conditions": {
            "hetero_atom_bin": "hetero_mid"
          },
          "weight": 0.45,
          "rationale": "Moderate heteroatom content balances hydrogen bonding against added hydrophobic scaffold, a common hydration optimum."
        },
        {
          "rule_id": "aromatic_surface_penalty",
          "conditions": {
            "aromatic_bin": "aromatic_mid"
          },
          "weight": -0.4,
          "rationale": "Extended flat aromatic surfaces hydrate poorly because pi systems force entropically costly water ordering."
        },
        {
          "rule_id": "downweight_ring_transfer",
          "conditions": {
            "ring_token_bin": "ring_token_none"
          },
          "weight": 0.15,
          "rationale": "Counter to the source ring relation: acyclic chains flexibly expose donors, but transfer is uncertain so weight stays small."
        },
        {
          "rule_id": "branch_burial_penalty",
          "conditions": {
            "branch_bin": "branch_high"
          },
          "weight": -0.2,
          "rationale": "Heavy branching sterically buries polar sites, reducing solvent-accessible hydrogen-bonding area."
        }
      ],
      "ridge": 1.4,
      "prior_scale": 0.3,
      "semantic_mass_start": 0.3,
      "semantic_mass_end": 0.08,
      "ucb_weight": 0.5,
      "gp_beta_start": 2.6,
      "gp_beta_end": 1.1,
      "gp_xi": 0.03,
      "confidence": 0.45,
      "hypothesis": "Downweights the uncertain source ring relation and bets that aromatic surface area rather than ring count governs hydration. Fails when polar heterocycles or heavily hydroxylated rings dominate the candidate pool."
    }
  ],
  "selected_skill_id": "polar_heteroatom_hydration_core_v3",
  "lesson": "Across both generations the polarity-grounded prior led on mean AUC and mean final best while the ring-reversal variants stalled on several seeds; with eight seeds per generation these are noisy rankings, so keep the mechanistically direct hydrogen-bonding prior deployed.",
  "revision_summary": "Retained the deployed heteroatom polarity and hydrocarbon-cavity mechanism, kept the source-grounded short-SMILES rule and the halogen hydrophobicity penalty, and trimmed early semantic mass slightly to reduce reliance on a thin semantic surrogate. The counter-hypothesis now downweights the uncertain source ring relation and centers on aromatic surface area and branching burial."
}
